import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FiArrowRight, FiCheckCircle, FiClock, FiGrid, FiLogOut, FiUser } from 'react-icons/fi';
import BrandMark from '../components/common/BrandMark';
import ErrorMessage from '../components/common/ErrorMessage';
import LoadingSpinner from '../components/common/LoadingSpinner';
import { useAuth } from '../hooks/useAuth';
import { getClientProfile } from '../services/siteService';

const ClientProfile = () => {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const load = async () => {
    setLoading(true);
    try {
      const data = await getClientProfile();
      setProfile(data.client);
      setError('');
    } catch (err) {
      setError(err.response?.data?.error || 'Unable to load your client workspace.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  if (loading) return (
    <div className="portal-page grid place-items-center min-h-screen">
      <LoadingSpinner message="Preparing your workspace…" />
    </div>
  );

  if (error) return (
    <div className="portal-page grid place-items-center min-h-screen">
      <ErrorMessage message={error} onRetry={load} />
    </div>
  );

  const stats = [
    { label: 'Active sites', value: profile?.stats?.active_sites || 0, icon: FiGrid },
    { label: 'Completed sites', value: profile?.stats?.completed_sites || 0, icon: FiCheckCircle },
    { label: 'Latest update', value: profile?.stats?.latest_update || 'N/A', icon: FiClock }
  ];

  return (
    <div className="portal-page min-h-screen">
      <div className="portal-shell profile-shell h-screen max-h-screen overflow-hidden">

        {/* ========== SIDEBAR ========== */}
        <aside className="portal-sidebar h-full flex flex-col py-4 px-3">
          {/* Brand */}
          <div className="flex items-center gap-2 px-2 mb-2">
            <BrandMark />
            <div className="text-xs">
              <div className="font-bold text-textPrimary">Aeroview 360</div>
              <div className="text-[10px] text-textMuted -mt-0.5">Client Portal</div>
            </div>
          </div>

          <div className="portal-rule my-2" />

          {/* Client Company */}
          <div className="flex items-center gap-3 px-2 py-2 bg-gray-50 rounded-lg">
            {profile?.company_logo ? (
              <img
                src={profile.company_logo}
                alt={profile.client_name}
                className="w-10 h-10 rounded-lg object-cover border border-gray-200 flex-shrink-0"
              />
            ) : (
              <div className="w-10 h-10 rounded-lg bg-primaryDark text-white flex items-center justify-center font-bold text-sm flex-shrink-0">
                {profile?.client_name?.slice(0, 2).toUpperCase()}
              </div>
            )}
            <div className="min-w-0 flex-1">
              <div className="font-semibold text-sm text-textPrimary truncate">
                {profile?.client_name}
              </div>
              <div className="text-[10px] text-textMuted uppercase tracking-wider">Client Workspace</div>
            </div>
          </div>

          <div className="portal-rule my-2" />

          {/* User & Logout */}
          <div className="mt-auto px-2">
            <div className="text-[10px] text-textMuted uppercase tracking-wider mb-1">Signed in as</div>
            <div className="font-medium text-sm text-textPrimary truncate">{user?.name}</div>
            <button
              onClick={() => { logout(); navigate('/login'); }}
              className="mt-2 flex items-center gap-1.5 text-xs text-textSecondary hover:text-red-600 transition-colors"
            >
              <FiLogOut size={14} />
              <span>Sign Out</span>
            </button>
          </div>
        </aside>

        {/* ========== MAIN CONTENT ========== */}
        <main className="portal-main h-full flex flex-col overflow-hidden p-4">

          {/* Header */}
          <header className="flex items-center gap-3 mb-3 flex-shrink-0">
            <div className="w-10 h-10 rounded-full bg-gray-100 flex items-center justify-center flex-shrink-0 overflow-hidden border border-gray-200">
              {profile?.company_logo ? (
                <img
                  src={profile.company_logo}
                  alt={profile.client_name}
                  className="w-full h-full object-cover"
                />
              ) : (
                <FiUser className="text-gray-400 text-lg" />
              )}
            </div>
            <div>
              <h1 className="text-lg font-bold text-textPrimary">
                Welcome Back, {user?.name?.split(' ')[0]}!
              </h1>
              <p className="text-xs text-textSecondary">
                {profile?.client_name} • Client Dashboard
              </p>
            </div>
          </header>

          {/* Content - Flex takes remaining space */}
          <div className="flex-1 flex flex-col gap-3 min-h-0">

            {/* Hero Section */}
            <section className="bg-white rounded-xl border border-gray-100 p-4 shadow-sm flex-shrink-0">
              <div className="text-[10px] font-semibold text-primaryDark uppercase tracking-wider">
                Client Dashboard
              </div>
              <h2 className="text-base font-bold text-textPrimary mt-0.5">
                Everything about your project, in one clear view.
              </h2>
              <p className="text-xs text-textSecondary mt-0.5">
                Select a site to access progress tours, videos, image folders, and final deliverables.
              </p>
              <button
                onClick={() => navigate('/sites')}
                className="mt-2 btn-primary text-sm py-1.5 px-4 inline-flex items-center gap-2"
              >
                View Project Sites <FiArrowRight size={14} />
              </button>
            </section>

            {/* Stats Cards */}
            <div className="grid grid-cols-3 gap-3 flex-shrink-0">
              {stats.map(({ label, value, icon: Icon }) => (
                <div className="bg-white rounded-xl border border-gray-100 p-3 shadow-sm text-center" key={label}>
                  <Icon className="text-primaryDark text-base mx-auto mb-1" />
                  <div className="text-xl font-bold text-textPrimary">{value}</div>
                  <div className="text-[10px] text-textMuted uppercase tracking-wider">{label}</div>
                </div>
              ))}
            </div>

            {/* Info Bar */}
            <div className="info-bar text-xs py-1.5 px-3 flex items-center gap-2 flex-shrink-0 bg-gray-50 border border-gray-100 rounded-lg">
              <FiCheckCircle size={14} className="text-primaryDark flex-shrink-0" />
              <span className="text-textSecondary">
                Your account only displays sites and project content assigned to {profile?.client_name}.
              </span>
            </div>

          </div>
        </main>
      </div>
    </div>
  );
};

export default ClientProfile;
